package tokenizer

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import scala.util.Try
import io.circe.Json
import io.circe.syntax._

/**
 * Tokenizer module for converting various input types to standardized string tokens.
 */

// ============================================================================
// Enums and Constants
// ============================================================================

sealed abstract class TokenType(val value: String)

object TokenType {
  case object STRING extends TokenType("string")
  case object NUMERIC extends TokenType("numeric")
  case object TEMPORAL extends TokenType("temporal")
  case object STRUCTURED extends TokenType("structured")
  case object BINARY extends TokenType("binary")
  case object NULL extends TokenType("null")

  def fromString(s: String): Option[TokenType] = s.toLowerCase match {
    case "string"     => Some(STRING)
    case "numeric"    => Some(NUMERIC)
    case "temporal"   => Some(TEMPORAL)
    case "structured" => Some(STRUCTURED)
    case "binary"     => Some(BINARY)
    case "null"       => Some(NULL)
    case _            => None
  }
}

// ============================================================================
// Structural types (traits)
// ============================================================================

trait Tokenizable {
  def toToken: String
}

trait HasLength {
  def length: Int
}

trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================
// Core Token Classes
// ============================================================================

/**
 * Immutable token representation.
 */
case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
) {
  /**
   * Return new token with additional metadata.
   */
  def withMetadata(newMeta: (String, Any)*): Token = {
    copy(metadata = metadata ++ newMeta.toMap)
  }
}

/**
 * Mutable batch of tokens.
 */
class MutableTokenBatch() {
  private var _tokens: List[Token] = Nil
  private var _processed: Boolean = false

  def tokens: List[Token] = _tokens.reverse

  def add(token: Token): Unit = {
    if (_processed) {
      throw new RuntimeError("Batch already processed")
    }
    _tokens = token :: _tokens
  }

  def markProcessed(): Unit = {
    _processed = true
  }
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/**
 * Covariant container - can return subtypes.
 */
class TokenContainer[+T](items: Seq[T]) {
  private val _items: Vector[T] = items.toVector

  def getAll: Vector[T] = _items

  def size: Int = _items.size

  def mapTokens(func: T => String): List[String] = {
    _items.map(func).toList
  }
}

/**
 * Contravariant sink - can accept supertypes.
 */
class TokenSink[-T] {
  private var _received: List[Any] = Nil

  def receive(item: T): Unit = {
    _received = item :: _received
  }

  def drain(): List[Any] = {
    val result = _received.reverse
    _received = Nil
    result
  }
}

/**
 * Invariant handler - exact type matching required.
 */
class BivariantHandler[T](private var _value: T) {
  def get: T = _value

  def set(value: T): Unit = {
    _value = value
  }

  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

/**
 * Abstract base tokenizer with generic input type.
 */
trait BaseTokenizer[T] {
  /**
   * Convert value to token.
   */
  def tokenize(value: T): Token

  /**
   * Lazy tokenization of multiple values.
   */
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

/**
 * Tokenizer for string and bytes types.
 */
class StringTokenizer(
    encoding: String = "UTF-8",
    normalizer: String => String = identity
) extends BaseTokenizer[Any] {
  override def tokenize(value: Any): Token = value match {
    case b: Array[Byte] =>
      val str = new String(b, encoding)
      Token(normalizer(str), TokenType.STRING)
    case s: String =>
      Token(normalizer(s), TokenType.STRING)
    case other =>
      Token(normalizer(other.toString), TokenType.STRING)
  }
}

/**
 * Tokenizer for numeric types with precision handling.
 */
class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] {
  override def tokenize(value: Any): Token = {
    val strValue = value match {
      case d: BigDecimal => s"%.${precision}f".format(d.toDouble)
      case d: Double     => s"%.${precision}f".format(d)
      case f: Float      => s"%.${precision}f".format(f.toDouble)
      case n: Number     => n.toString
      case _             => value.toString
    }

    Token(strValue, TokenType.NUMERIC, Map("original_type" -> value.getClass.getSimpleName))
  }
}

/**
 * Tokenizer for date/time types.
 */
class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[Any] {
  private val IsoFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val DateFormat = DateTimeFormatter.ISO_LOCAL_DATE

  override def tokenize(value: Any): Token = {
    val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse {
      value match {
        case _: LocalDateTime => IsoFormat
        case _               => DateFormat
      }
    }

    val strValue = value match {
      case dt: LocalDateTime => dt.format(fmt)
      case d: LocalDate     => d.format(fmt)
      case _                 => value.toString
    }

    Token(strValue, TokenType.TEMPORAL)
  }
}

// ============================================================================
// Universal Tokenizer
// ============================================================================

class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize(value: Any): Token = value match {
    case null => tokenizeNull
    case t: Tokenizable =>
      Token(t.toToken, TokenType.STRUCTURED)
    case s: String =>
      stringTokenizer.tokenize(s)
    case b: Array[Byte] =>
      stringTokenizer.tokenize(b)
    case n: Int =>
      numericTokenizer.tokenize(n)
    case n: Long =>
      numericTokenizer.tokenize(n)
    case n: Double =>
      numericTokenizer.tokenize(n)
    case n: BigDecimal =>
      numericTokenizer.tokenize(n)
    case dt: LocalDateTime =>
      temporalTokenizer.tokenize(dt)
    case d: LocalDate =>
      temporalTokenizer.tokenize(d)
    case other =>
      Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }

  def tokenizeNull: Token = Token("NULL", TokenType.NULL)
}

// ============================================================================
// Token Registry
// ============================================================================

class TokenRegistry[T] {
  private var _registry: Map[String, TokenContainer[T]] = Map.empty
  private var _handlers: List[T => Option[Token]] = Nil

  def register(key: String, container: TokenContainer[T]): Unit = {
    _registry += (key -> container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    _handlers = handler :: _handlers
  }

  def process(key: String): List[Option[Token]] = {
    _registry.get(key) match {
      case Some(container) =>
        container.getAll.toList.map { item =>
          _handlers.reverse.collectFirst { h =>
            h(item) match {
              case Some(t) => t
            }
          }.orElse(None)
        }
      case None => Nil
    }
  }
}

// ============================================================================
// Higher-Kinded Type Simulation / Proper Monads
// ============================================================================

class TokenFunctor[T](private val value: T) {
  def map[U](func: T => U): TokenFunctor[U] = new TokenFunctor(func(value))
  def flatMap[U](func: T => TokenFunctor[U]): TokenFunctor[U] = func(value)
  def getOrElse(default: T): T = if (value != null) value else default
  def get: T = value
}

class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] = {
    new TokenMonad(funcWrapped.get(this.get))
  }
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

class JsonTokenizer(pretty: Boolean = false) {
  def tokenize(value: Json): Token = {
    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = path.split('.')
    val target = parts.foldLeft(Option(value)) { (current, part) =>
      current.flatMap { c =>
        if (part.forall(_.isDigit)) {
          c.asArray.flatMap(_.lift(part.toInt))
        } else {
          c.asObject.flatMap(_.apply(part))
        }
      }
    }
    target.map(tokenize)
  }
}

// ============================================================================
// Whitespace Tokenizer
// ============================================================================

class WhitespaceTokenizer(
    val lowercase: Boolean = false,
    val minLength: Int = 0,
    val maxLength: Option[Int] = None,
    val stripPunctuation: Boolean = false
) {
  private val Punctuation = ".,!?;:'\"()[]{}".toSet

  private def processToken(word: String): Option[String] = {
    var processed = if (stripPunctuation) {
      word.filterNot(Punctuation.contains)
    } else {
      word
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) {
      None
    } else {
      val finalWord = maxLength match {
        case Some(max) if processed.length > max => processed.take(max)
        case _                                   => processed
      }
      if (finalWord.nonEmpty) Some(finalWord) else None
    }
  }

  def tokenize(text: String): List[Token] = {
    text.split("\\s+").toList.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }
  }

  def tokenizeToStrings(text: String): List[String] = {
    tokenize(text).map(_.value)
  }

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    var currentPos = 0
    text.split("\\s+").toList.flatMap { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length
      currentPos = end
      processToken(word).map(processed => (processed, start, end))
    }
  }

  def countTokens(text: String): Int = tokenize(text).size
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

class TokenizerBuilder[T] private (
    normalizers: List[String => String],
    validators: List[T => Boolean],
    metadata: Map[String, Any]
) {
  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    new TokenizerBuilder(normalizers :+ normalizer, validators, metadata)
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    new TokenizerBuilder(normalizers, validators :+ validator, metadata)
  }

  def withMetadata(newMeta: (String, Any)*): TokenizerBuilder[T] = {
    new TokenizerBuilder(normalizers, validators, metadata ++ newMeta.toMap)
  }

  def build(): T => Token = { (value: T) =>
    for (validator <- validators) {
      if (!validator(value)) {
        throw new IllegalArgumentException(s"Validation failed for $value")
      }
    }

    var strValue = value.toString
    for (normalizer <- normalizers) {
      strValue = normalizer(strValue)
    }

    Token(strValue, TokenType.STRING, metadata)
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder(Nil, Nil, Map.empty)
}

